        ...props,
        value: undefined,
        defaultValue: undefined,
        onUpdate: undefined,
    });

    const {inputProps: relativeDateProps} = useRelativeDateFieldProps(relativeDateState, {
        ...props,
        value: undefined,
        defaultValue: undefined,
        onUpdate: undefined,
    });

