        calendarButtonProps: {
            size: getButtonSizeForInput(props.size),
            disabled: state.disabled,
            'aria-label': t('Calendar'),
            'aria-haspopup': 'dialog',
            'aria-expanded': isOpen,
            view: 'flat-secondary',
            onClick: () => {
                state.setActive(true);
