            offset: props.popupOffset,
            className: props.popupClassName,
            style: props.popupStyle,
            returnFocus: false,
        },
        calendarProps: {
            ref: calendarRef,
            size: props.size === 's' ? 'm' : props.size,
            readOnly: props.readOnly,
            value: state.selectedDate,
            onUpdate: (v) => {
                datePickerState.setDateValue(v);
